import type { Locale } from 'date-fns';

// Holds the date-fns locale of the active UI language. Kept apart from the
// loader table in dateFnsLocale.ts so only these few bytes sit in the boot
// chunk; the table itself is a lazy chunk.
let activeLocale: Locale | null = null;

export function getLoadedDateLocale(): Locale | null {
  return activeLocale;
}

export function setLoadedDateLocale(locale: Locale): void {
  activeLocale = locale;
}
